solutions.naive:
class Solution:
    def scoreOfParentheses(self, s: str) -> int:
        def score(l,r):
            total=bal=0; start=l
            for i in range(l,r):
                bal += 1 if s[i]=='(' else -1
                if bal==0:
                    total += 1 if i==start+1 else 2*score(start+1,i)
                    start=i+1
            return total
        return score(0,len(s))

solutions.better:
class Solution:
    def scoreOfParentheses(self, s: str) -> int:
        st=[0]
        for c in s:
            if c=='(': st.append(0)
            else:
                v=st.pop(); st[-1]+=max(2*v,1)
        return st[0]

